"""ds4_idx_score.py — ctypes wrapper for libds4idx.so (container/native/ds4_idx_score.hip):
the hand-HIP WMMA decode indexer scorer that reads the fp8 paged cache directly.
Used by ds4_tl_indexer.fp8_paged_mqa_logits_tl under DS4_IDX_HIP (default on)."""
import ctypes
import os

import torch

_LIB_PATHS = [
    os.environ.get("DS4_IDX_HIP_LIB", ""),
    os.path.join(os.path.dirname(os.path.abspath(__file__)), "libds4idx.so"),
    "/opt/venv/lib64/python3.12/site-packages/libds4idx.so",
]
_LIB = None
# persistent workgroups: 120 measured best at 100K-512K (40 -> 2x slower, 160+ slightly worse)
_GRID = int(os.environ.get("DS4_IDX_HIP_GRID", "120"))


def _load():
    global _LIB
    if _LIB is None:
        for p in _LIB_PATHS:
            if p and os.path.exists(p):
                lib = ctypes.CDLL(p)
                lib.ds4_idx_score.argtypes = [
                    ctypes.c_void_p, ctypes.c_long, ctypes.c_void_p, ctypes.c_int, ctypes.c_int,
                    ctypes.c_void_p, ctypes.c_void_p, ctypes.c_void_p,
                    ctypes.c_void_p, ctypes.c_long, ctypes.c_int, ctypes.c_int,
                    ctypes.c_int, ctypes.c_void_p,
                ]
                lib.ds4_idx_score.restype = ctypes.c_int
                _LIB = lib
                break
        if _LIB is None:
            raise RuntimeError("libds4idx.so not found")
    return _LIB


def eligible(H: int, dim: int, bs: int, fp8_dtype) -> bool:
    return H == 64 and dim == 128 and bs % 64 == 0 and fp8_dtype is torch.float8_e4m3fn


def score(flat: torch.Tensor, bt_row: torch.Tensor, npg: int, bs: int,
          q_rows: torch.Tensor, w_rows: torch.Tensor, ke_rows: torch.Tensor,
          out: torch.Tensor, ntiles: int) -> None:
    """out[r, :ntiles*64] = scores of q_rows[r] vs the paged cache, -inf at
    columns >= ke_rows[r]. out rows may be strided (out.stride(0)); its columns
    must be contiguous. q_rows bf16 [nr*64, 128] contiguous; w_rows fp32
    [nr, 64] contiguous; ke_rows int32 [nr] contiguous; bt_row int32 [>= npg]."""
    lib = _load()
    assert flat.dtype == torch.uint8 and flat.stride(1) == 1
    assert q_rows.dtype == torch.bfloat16 and q_rows.is_contiguous()
    assert w_rows.dtype == torch.float32 and w_rows.is_contiguous()
    assert ke_rows.dtype == torch.int32 and ke_rows.is_contiguous()
    assert bt_row.dtype == torch.int32 and bt_row.is_contiguous()
    assert out.dtype == torch.float32 and out.stride(1) == 1
    nr = w_rows.shape[0]
    rc = lib.ds4_idx_score(
        ctypes.c_void_p(flat.data_ptr()), ctypes.c_long(flat.stride(0)),
        ctypes.c_void_p(bt_row.data_ptr()), int(npg), int(bs),
        ctypes.c_void_p(q_rows.data_ptr()), ctypes.c_void_p(w_rows.data_ptr()),
        ctypes.c_void_p(ke_rows.data_ptr()),
        ctypes.c_void_p(out.data_ptr()), ctypes.c_long(out.stride(0)), int(nr), int(ntiles),
        _GRID, ctypes.c_void_p(torch.cuda.current_stream().cuda_stream))
    if rc != 0:
        raise RuntimeError(f"ds4_idx_score failed: {rc}")
